import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Proposta di aggiornamento di Specifications.md alla v1.2","description":"","frontmatter":{},"headers":[],"relativePath":"spec-v1.2-proposta.md","filePath":"spec-v1.2-proposta.md"}'),d={name:"spec-v1.2-proposta.md"};function l(n,e,r,c,s,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="proposta-di-aggiornamento-di-specifications-md-alla-v1-2" tabindex="-1">Proposta di aggiornamento di <code>Specifications.md</code> alla v1.2 <a class="header-anchor" href="#proposta-di-aggiornamento-di-specifications-md-alla-v1-2" aria-label="Permalink to &quot;Proposta di aggiornamento di `Specifications.md` alla v1.2&quot;">​</a></h1><blockquote><p><strong>Nota (2026-11-02).</strong> Il contenuto di questa proposta è stato recepito in <code>Specifications.md</code> v1.4 (Appendice C.4), dopo una verifica sul codice e sugli ADR accettati più recenti, che prevalgono, salvo ADR-0023 (manifest di aggiornamento firmato), che resta in stato <em>proposta</em>, e ADR-0035 (barra di stato opzionale), accettato e recepito poi nella v1.5. Il documento resta come storia; il testo che segue non è aggiornato.</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>proposta all&#39;owner (lo spec non è stato modificato)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-30</td></tr><tr><td><strong>Base</strong></td><td><code>Specifications.md</code> v1.1 (23/10/2026)</td></tr><tr><td><strong>Fonti</strong></td><td>ADR 0009–0035 in stato <em>proposta</em> (più 0025 e 0031), lavoro dei passi 1–5 dell&#39;analisi dei gap del 2026-10-30</td></tr><tr><td><strong>Come usarla</strong></td><td>ogni voce indica la sezione, cosa dice oggi lo spec, la modifica proposta e l&#39;ADR di origine. Le decisioni che spettano all&#39;owner sono raccolte nel §1.</td></tr></tbody></table><p>Lo spec v1.1 descrive il prodotto di M0–M5. Da allora sono arrivati 24 ADR in stato <em>proposta</em> (M2–M10) e le correzioni dell&#39;analisi dei gap, e il codice ne ha implementata la gran parte. Questa proposta raccoglie tutto in un solo posto, così la v1.2 torna a descrivere il prodotto reale. Le voci marcate <strong>[nuovo]</strong> vengono dai passi 1–5 dell&#39;analisi del 2026-10-30 e non hanno un ADR dedicato: sono descritte nei rispettivi commit e test.</p><hr><h2 id="_1-decisioni-che-spettano-all-owner" tabindex="-1">1. Decisioni che spettano all&#39;owner <a class="header-anchor" href="#_1-decisioni-che-spettano-all-owner" aria-label="Permalink to &quot;1. Decisioni che spettano all&#39;owner&quot;">​</a></h2><p>Prima di recepire le modifiche servono queste scelte. Senza una scelta esplicita vale la colonna «Proposta».</p><table tabindex="0"><thead><tr><th>#</th><th>Decisione</th><th>Proposta</th><th>ADR</th></tr></thead><tbody><tr><td>1</td><td>A-03: la Web UI diventa anche un editor (workbench del vault)</td><td>Accettare, con le eccezioni di parità di ADR-0029 e il rischio E2EE dichiarato</td><td>0029/0030</td></tr><tr><td>2</td><td>Slides passa da P2 a P1 (già realizzata)</td><td>Accettare</td><td>0027</td></tr><tr><td>3</td><td>Random note passa da P2 a P1 (già realizzata)</td><td>Accettare</td><td>0015</td></tr><tr><td>4</td><td>Status bar: eliminata (ADR-0026) o barra compatta opzionale</td><td>Barra opzionale spenta per default (ADR-0035); il word count resta nel pannello Statistiche</td><td>0026/0035</td></tr><tr><td>5</td><td>Envelope della VMK con AAD (formato v2), prima o dopo l&#39;audit esterno</td><td>Prima dell&#39;audit, in due rilasci (lettura v2, poi scrittura v2)</td><td>0034</td></tr><tr><td>6</td><td>Rilasci desktop non firmati finché mancano i certificati</td><td>Ammessi come prerelease con avviso e senza auto-update; lo stabile richiede la firma</td><td>0031</td></tr><tr><td>7</td><td>Eccezioni alla regola «mai alle tabelle altrui»</td><td>Accettare le eccezioni elencate (admin, privacy, jobs, notify, …) e ridurre in seguito quelle di scrittura</td><td>0033</td></tr><tr><td>8</td><td>Limite di dimensione dei file: Config Profile (<code>sync.max_file_size_bytes</code>) e impostazione di sistema (<code>files.max_size_bytes</code>)</td><td>Il default del profilo deriva dall&#39;impostazione di sistema (oggi è fisso a 100 MB): da implementare</td><td>[nuovo]</td></tr><tr><td>9</td><td>Timeout di blocco dei vault privati: default</td><td>0 = mai (la VMK resta nel keychain, come in §3.8.2); configurabile da utente e da profilo</td><td>[nuovo]</td></tr><tr><td>10</td><td>Nome «Nodus» nell&#39;intestazione dello spec</td><td>Rimuoverlo (rebrand completato, <code>docs/release/rebrand-inventory.md</code>)</td><td>—</td></tr></tbody></table><hr><h2 id="_2-intestazione-e-registro" tabindex="-1">2. Intestazione e registro <a class="header-anchor" href="#_2-intestazione-e-registro" aria-label="Permalink to &quot;2. Intestazione e registro&quot;">​</a></h2><ul><li><strong>Intestazione:</strong> «Versione documento: 1.2 — ADR 0009–0035 recepiti (vedi Appendice C)», nuova data. Nome del prodotto senza «(già &quot;Nodus&quot; come nome in codice)».</li><li><strong>Appendice C.1, nuove decisioni</strong> (proposta di numerazione):</li></ul><table tabindex="0"><thead><tr><th>ID</th><th>Tema</th><th>Decisione</th><th>Sezioni</th></tr></thead><tbody><tr><td>D-09</td><td>Workbench web</td><td>La Web UI include un workbench del vault con il core del desktop in WebAssembly (ADR-0029/0030)</td><td>§0.1, §0.3, §2.8, §4.4</td></tr><tr><td>D-10</td><td>Shell desktop</td><td>Header, ribbon, sidebar destra con footer di stato; barra di stato opzionale (ADR-0026/0035)</td><td>§2.2.1, §4.2</td></tr><tr><td>D-11</td><td>Proprietà delle tabelle</td><td>Un pacchetto sqlc per modulo, eccezioni dichiarate e verificate (ADR-0033)</td><td>§1.1, §4.3</td></tr><tr><td>D-12</td><td>Excalidraw</td><td>Fork <code>@zsviczian/excalidraw</code>, funzioni dei plugin Obsidian, nessun motore di script (ADR-0024/0028)</td><td>§2.7</td></tr></tbody></table><ul><li><strong>Appendice C.2, rischi:</strong><ul><li>la riga «Web UI anello debole dell&#39;E2EE» va estesa alla scrittura dei vault privati dal workbench, con le mitigazioni di ADR-0029 (CSP dedicata, SRI, blocco per inattività, cancellazione della copia OPFS, flag <code>web_workbench</code>);</li><li>nuova riga «Rilasci non firmati» (ADR-0031).</li></ul></li></ul><hr><h2 id="_3-modifiche-per-sezione" tabindex="-1">3. Modifiche per sezione <a class="header-anchor" href="#_3-modifiche-per-sezione" aria-label="Permalink to &quot;3. Modifiche per sezione&quot;">​</a></h2><h3 id="§0-introduzione" tabindex="-1">§0 Introduzione <a class="header-anchor" href="#§0-introduzione" aria-label="Permalink to &quot;§0 Introduzione&quot;">​</a></h3><ul><li><strong>§0.1 punto 3 e §0.3 A-03</strong> (D-09, ADR-0029). Oggi: «La Web UI del cloud non è un editor». Proposta, dal testo di ADR-0029: «La Web UI del cloud comprende console amministrativa, area utente e un workbench del vault con le stesse funzioni del client desktop, salvo le eccezioni di ADR-0029 (updater, vault su cartella locale, integrazioni native del sistema operativo). Il workbench web è un dispositivo di sync come gli altri: online-first, con cache locale nel browser.» Correzioni rispetto alla decisione originale: <ul><li>il blocco per inattività del workbench è fisso a 15 minuti;</li><li>c&#39;è un solo workbench per browser (Web Lock <code>memobrain-workbench</code>).</li></ul></li></ul><h3 id="§1-architettura-e-flussi" tabindex="-1">§1 Architettura e flussi <a class="header-anchor" href="#§1-architettura-e-flussi" aria-label="Permalink to &quot;§1 Architettura e flussi&quot;">​</a></h3><ul><li><strong>§1.1 / §1.2</strong> (ADR-0030): <ul><li>il core Go del desktop gira anche come <code>memobrain-core.wasm</code> (<code>GOOS=js</code>) in un Web Worker;</li><li>interfaccia <code>Host</code>, dispatcher <code>internal/rpc</code>, <code>App.Services()</code> come elenco unico dei servizi;</li><li>«nessun accesso incrociato alle tabelle» rinvia alle eccezioni di §4.3 (ADR-0033).</li></ul></li><li><strong>§1.3 Redirect (D-08)</strong> [nuovo]: <ul><li><strong>regola (b):</strong> Keycloak non fa redirect su un <code>redirect_uri</code> non registrato, mostra una pagina d&#39;errore. In modalità <code>auto</code> il client fa quindi un controllo preliminare dell&#39;endpoint di autorizzazione, senza seguire i redirect. Una risposta 400 che cita <code>redirect_uri</code> fa passare allo scheme <code>memobrain://</code> prima di aprire il browser (verificato su Keycloak 26).</li><li><strong>regola (c):</strong> il valore del Config Profile è <code>auth.redirect_mode = auto|loopback|custom_scheme</code>. La variabile <code>MEMOBRAIN_AUTH_REDIRECT</code> ha la precedenza (uso di test).</li></ul></li><li><strong>§1.6 Topologia</strong> (ADR-0022, [nuovo]): <ul><li>allo shutdown <code>/readyz</code> risponde 503, poi drain di <code>SHUTDOWN_DRAIN</code> (default 5 s), chiusura degli stream e <code>Shutdown</code>; <code>terminationGracePeriodSeconds</code> &gt; drain + <code>SHUTDOWN_TIMEOUT</code>; almeno 2 repliche;</li><li>dietro un reverse proxy va impostato <code>TRUSTED_PROXIES</code> (CIDR), altrimenti il limite di richieste per IP vede solo l&#39;IP del proxy.</li></ul></li></ul><h3 id="§2-2-1-matrice-di-parita" tabindex="-1">§2.2.1 Matrice di parità <a class="header-anchor" href="#§2-2-1-matrice-di-parita" aria-label="Permalink to &quot;§2.2.1 Matrice di parità&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Riga</th><th>Oggi</th><th>Proposta</th><th>ADR</th></tr></thead><tbody><tr><td>Word count (<code>statusbar</code>, P0)</td><td>«Parole, caratteri, selezione»</td><td>Pannello <em>Statistiche</em> (parole, caratteri, selezione, riga:colonna); barra di stato compatta opzionale, spenta per default</td><td>0026, 0035</td></tr><tr><td>Pannelli, tab, split</td><td>—</td><td>Header, ribbon (nuova cartella, nota, lavagna, disegno, base, export PDF/immagine), tab bloccabili (<code>pinned</code> in <code>workspace.json</code>) con «Chiudi a destra/sinistra/altre/tutte», selettore vault nel footer sinistro, avatar/login</td><td>0026</td></tr><tr><td>Appearance</td><td>—</td><td>Toggle chiaro/scuro nell&#39;header; <code>system</code> resta nelle impostazioni</td><td>0026</td></tr><tr><td>Slides (<code>slides</code>)</td><td>P2, «Separatore <code>---</code>»</td><td><strong>P1</strong>; <code>---</code> preceduto da riga vuota, fuori da frontmatter, codice e <code>$$</code>; note del presentatore dopo <code>Note:</code>; chiavi <code>slide-transition</code>, <code>slide-theme</code>, <code>slide-progress</code>, <code>slide-numbers</code>, <code>slide-notes</code>; comandi <code>slides:start</code>, <code>slides:start-here</code></td><td>0027</td></tr><tr><td>Random note</td><td>P2</td><td><strong>P1</strong> (realizzata)</td><td>0015</td></tr><tr><td>Graph view</td><td>«Canvas/WebGL»</td><td>Canvas 2D con <code>d3-force</code> in un Web Worker (WebGL come riserva); <code>maxNodes</code> 20.000 (oltre: <code>truncated</code>); timelapse su <code>created</code> del frontmatter, altrimenti <code>mtime</code>; impostazioni in <code>.memobrain/graph.json</code></td><td>0013</td></tr><tr><td>Bases</td><td>«File <code>.base</code> (YAML)»</td><td>Viste <code>table</code>/<code>cards</code>; motore unico Go (<code>BasesAPI</code>); degrado non distruttivo; round-trip <code>yaml.v3</code> che preserva chiavi sconosciute e commenti; scrittura solo su azione esplicita con <code>expectedHash</code></td><td>0014</td></tr><tr><td>Canvas</td><td>«nodi testo/nota/media/link/gruppo»</td><td>Testo modificabile in <code>&lt;textarea&gt;</code>, Markdown reso a riposo; <code>![[x.canvas]]</code> come SVG statico; doppio clic apre l&#39;editor; salvataggio con debounce di 1 s</td><td>0010</td></tr><tr><td>Templates / Daily notes</td><td><code>{{date}}</code>, <code>{{time}}</code>, <code>{{title}}</code></td><td>Più <code>{{date:FMT}}</code>/<code>{{time:FMT}}</code> (sottoinsieme Moment), variabili sconosciute lasciate letterali, <code>/</code> nel formato crea sottocartelle; libreria di gruppo da <code>templates.library_share_id</code>; impostazione «Template di ogni nuova nota» (<code>newNoteTemplate</code>)</td><td>0015</td></tr><tr><td>Note composer</td><td>—</td><td>Unione in tre passi (destinazione, link, cestino) con rollback; il frontmatter della sorgente non viene unito</td><td>0015</td></tr><tr><td>Bookmarks / Page preview</td><td>—</td><td>Bookmark in <code>.memobrain/bookmarks.json</code>; anteprima con Cmd/Ctrl + hover per 350 ms (<code>pagePreview</code>, <code>pagePreviewAlways</code>), nessuna anteprima annidata</td><td>0016</td></tr><tr><td>File recovery</td><td>—</td><td>Snapshot locali guidati dal watcher (5 min), solo testo ≤ 5 MB, tetto 500 MB, retention 7 giorni; motivi <code>periodic</code>, <code>pre-restore</code>, <code>pre-sync-overwrite</code> (prima che un merge sostituisca contenuto non ancora sul server); dialogo unico locale + cloud</td><td>0018, [nuovo]</td></tr><tr><td>Embedded search</td><td>—</td><td>Blocco <code>query</code> con <code>sort:</code>, <code>limit:</code> (max 500), <code>view:</code>, <code>context:</code>, <code>self:</code>; nota ospitante esclusa (<code>queryIncludeHost</code>)</td><td>0019</td></tr><tr><td>Importer (P1)</td><td>elenco sorgenti</td><td>Destinazione <code>Imports/&lt;sorgente&gt;-&lt;data&gt;/</code> con <code>Import report.md</code>; mai sovrascrittura; anteprima identica all&#39;import; tetti per gli zip; HTML convertito in Markdown puro; Google Keep da JSON <strong>e da HTML</strong> (quando manca il JSON)</td><td>0017</td></tr><tr><td>Drawing</td><td>—</td><td>Flag <code>drawings</code> con sotto-flag <code>drawing_latex</code>, <code>drawing_mermaid</code>, <code>drawing_auto_export</code>, <code>drawing_actions</code> (accesi per default)</td><td>0024</td></tr></tbody></table><h3 id="§2-2-2-obsidian-flavored-markdown" tabindex="-1">§2.2.2 Obsidian Flavored Markdown <a class="header-anchor" href="#§2-2-2-obsidian-flavored-markdown" aria-label="Permalink to &quot;§2.2.2 Obsidian Flavored Markdown&quot;">​</a></h3><ul><li><strong>Footnote <code>^[inline]</code></strong> [nuovo]: <ul><li>indicizzate dai due parser (Go e TS) come <code>^1</code>, <code>^2</code>, … in ordine di documento, accanto alle etichette <code>[^x]</code>; codice inline, escape <code>\\^[</code> e parentesi non chiuse non contano;</li><li>rese nel reading view e nell&#39;export HTML, numerate insieme alle footnote con etichetta;</li><li>fixture <code>footnote-inline-edge</code> in <code>shared/conformance/markdown/</code>.</li><li>Limite: in Live Preview restano testo.</li></ul></li></ul><h3 id="§2-3-editor-e-rendering" tabindex="-1">§2.3 Editor e rendering <a class="header-anchor" href="#§2-3-editor-e-rendering" aria-label="Permalink to &quot;§2.3 Editor e rendering&quot;">​</a></h3><ul><li><strong>§2.3.2 Export</strong> (ADR-0019): <ul><li>HTML con <code>ExportAPI.SaveHTML</code>, autonomo (data URI con tetti 8/48 MB, MathML, CSP <code>default-src &#39;none&#39;</code>), wikilink come testo;</li><li>PDF solo dal dialogo di stampa di sistema (Wails v2 non stampa in PDF senza dialogo).</li></ul></li><li><strong>§2.3.3</strong> (ADR-0027): fixture condivise anche per le slide (<code>shared/conformance/slides/</code>), con estrattore in <code>packages/markdown</code> e in <code>internal/parser</code>.</li></ul><h3 id="§2-4-indicizzazione-e-ricerca" tabindex="-1">§2.4 Indicizzazione e ricerca <a class="header-anchor" href="#§2-4-indicizzazione-e-ricerca" aria-label="Permalink to &quot;§2.4 Indicizzazione e ricerca&quot;">​</a></h3><ul><li><strong>Rilevanza</strong> [nuovo]: <ul><li>BM25 sui termini di testo della query, con frequenze dall&#39;indice FTS e lunghezza in parole, più un peso per il termine presente nel titolo;</li><li>le query senza testo (<code>tag:</code>, <code>path:</code>, regex) ordinano per numero di corrispondenze.</li></ul></li><li><strong>Snippet evidenziati</strong> [nuovo]: ogni risultato porta gli intervalli corrispondenti (UTF-16); lo snippet è centrato sulla prima corrispondenza nelle righe lunghe; i termini negati non sono evidenziati.</li><li><strong>Prestazioni</strong> (ADR-0020): <ul><li>cache in RAM dei candidati con budget di 512 MB (circa 210 MB a 50.000 note), oltre il quale la ricerca passa allo streaming da SQLite;</li><li>indicizzazione a batch (250 note o 16 MB per transazione).</li><li>Limite dichiarato: regex su tutto il vault di 50.000 note circa 0,45 s, oltre i 200 ms.</li></ul></li><li><strong>Punto 4</strong> (ADR-0010/0024): etichette «Disegno: X» / «Lavagna: X»; anche i nomi dei frame dei disegni sono indicizzati.</li></ul><h3 id="§2-5-moduli-del-client" tabindex="-1">§2.5 Moduli del client <a class="header-anchor" href="#§2-5-moduli-del-client" aria-label="Permalink to &quot;§2.5 Moduli del client&quot;">​</a></h3><ul><li><strong><code>updater</code></strong> (ADR-0023): <ul><li>manifest <code>manifest.json</code> (schema 1) con firma ed25519 separata, chiave distinta dai certificati di code signing, firma verificata prima del parse;</li><li>anti-rollback con <code>sequence</code> e <code>min_version</code>; canali <code>stable/</code> e <code>beta/</code>;</li><li>controllo dopo 45 s dall&#39;avvio e ogni 24 h; opt-out con <code>MEMOBRAIN_UPDATES=off</code>;</li><li>due sole GET senza identificativi.</li></ul></li><li><strong><code>store</code></strong> (ADR-0030): driver scelto per build tag; nel browser <code>internal/sqlitejs</code> su sqlite-wasm <code>opfs-sahpool</code>, file system tramite lo shim <code>fs</code> su OPFS.</li><li><strong><code>auth</code></strong> (ADR-0030): modalità <code>Hosted</code> nel browser (token dalla pagina, nessun keychain).</li><li><strong><code>sync</code></strong> [nuovo]: <ul><li>un file oltre il limite viene messo da parte con <code>FILE_TOO_LARGE</code> prima di essere letto o cifrato;</li><li>un blob rifiutato dal server come troppo grande ferma solo quel file, non l&#39;intero push.</li></ul></li><li><strong><code>crypto</code></strong> [nuovo]: blocco per inattività attivo (controllo ogni 30 s), vedi §3.8.2.</li></ul><h3 id="§2-6-servizio-cloud" tabindex="-1">§2.6 Servizio cloud <a class="header-anchor" href="#§2-6-servizio-cloud" aria-label="Permalink to &quot;§2.6 Servizio cloud&quot;">​</a></h3><ul><li><strong>§2.6.2 / §2.6.5, privacy</strong> (ADR-0021): <ul><li>la cancellazione dell&#39;account anonimizza subito la riga <code>users</code> e fa il soft-delete dei vault;</li><li>dopo <code>privacy.account_purge_days</code> (default 30) il job li elimina definitivamente;</li><li>l&#39;account Keycloak viene disabilitato, non eliminato (limite dichiarato).</li></ul></li><li><strong>§2.6.4 Condivisione</strong> (ADR-0011): <ul><li>ogni share, anche di un documento, è un mount a sé in <code>&lt;data&gt;/mounts/&lt;share_id&gt;/</code>; alla revoca l&#39;utente sceglie se eliminare la copia o conservarla in <code>&lt;data&gt;/kept/</code>;</li><li>un grant a un gruppo è accettato da qualsiasi membro per tutto il gruppo; il rifiuto vale solo per i grant a utente (altrimenti <code>409 INVALID_STATE</code>).</li><li>Limiti: nessuna cessione di proprietà; un <code>manager</code> non crea né revoca share.</li></ul></li><li><strong>§2.6.6 Config Profile</strong> (ADR-0011, [nuovo]): <ul><li><code>version</code> è una revisione globale (<code>settings[&#39;config.revision&#39;]</code>);</li><li>le chiavi <code>locked</code> sono unite tra profilo globale e gruppi;</li><li>contratto in <code>api/config-profile.schema.json</code>;</li><li>chiavi applicate dal client: <code>sync.interval_seconds</code>, <code>sync.max_file_size_bytes</code>, <code>auth.redirect_mode</code>, <code>security.vault_lock_minutes</code> (nuova sezione <code>security</code>), <code>editor.*</code>, <code>appearance.*</code> (più <code>appearance.statusBar</code> se si accetta ADR-0035), <code>daily_notes.*</code>, <code>templates.library_share_id</code>, <code>features.*</code> (<code>web_workbench</code>, <code>chat</code>, <code>drawings</code> e sotto-flag; <code>envelope_v2</code> con ADR-0034);</li><li>un flag assente vale «spento», salvo i default di prodotto.</li></ul></li></ul><h3 id="§2-7-excalidraw" tabindex="-1">§2.7 Excalidraw <a class="header-anchor" href="#§2-7-excalidraw" aria-label="Permalink to &quot;§2.7 Excalidraw&quot;">​</a></h3><ul><li><strong>§2.7.1</strong> (ADR-0024): <ul><li>embed di parti con <code>#frame=</code>, <code>#clippedframe=</code>, <code>#group=</code>, <code>#area=</code> e allineamento <code>|left|right|center|left-wrap|right-wrap</code>;</li><li>metadati in <code>customData.memobrain</code>, impostazioni per vault in <code>.memobrain/drawing.json</code>, nessun <code>.excalidraw.md</code>;</li><li>soglia di 10 MB anche per singolo file inserito.</li></ul></li><li><strong>§2.7.2</strong> (ADR-0010/0024): <ul><li>export PNG/SVG/PDF/JSON salvato nel vault, auto-export <code>X.excalidraw[.light|.dark].png|svg</code>;</li><li>formule LaTeX (<code>mathjax-full</code> 3.2.2, lazy), Mermaid→Excalidraw (<code>securityLevel: &#39;strict&#39;</code>), operazioni booleane, schede-nota, presentazione per frame;</li><li>azioni native <code>drawing:&lt;id&gt;</code>, senza motore di script;</li><li>import di <code>.excalidraw.md</code> e <code>.excalidrawlib</code>;</li><li>il rename riscrive i <code>[[link]]</code> dentro i <code>.excalidraw</code> (non nei canvas).</li></ul></li><li><strong>§2.7.3</strong> (ADR-0028/0033): <ul><li>dipendenza <code>npm:@zsviczian/excalidraw@0.18.145</code> (fork MIT del plugin Obsidian: lazo, secchiello, disegno per forma), caricata come script della stessa origine;</li><li>la versione 0.18.1 di ADR-0010 è superata;</li><li>gate offline in CI con <code>web/e2e-security/excalidraw-offline.spec.ts</code>: disegno con testo CJK, nessuna richiesta esterna;</li><li>il fallback <code>esm.sh</code> dei font è riscritto dalla build verso gli asset dell&#39;app.</li><li>Limiti: script di 6,5 MB fuori dal budget del bundle; due copie di Mermaid.</li></ul></li></ul><h3 id="§2-8-web-ui" tabindex="-1">§2.8 Web UI <a class="header-anchor" href="#§2-8-web-ui" aria-label="Permalink to &quot;§2.8 Web UI&quot;">​</a></h3><ul><li><strong>§2.8.2</strong> (ADR-0029): schermata «Apri vault» (<code>/vaults/:id/open</code>); dispositivo <code>platform: &quot;web&quot;</code>; copia del vault in OPFS; flag <code>web_workbench</code>, acceso per default. <ul><li>Limiti: nessuna PWA offline; Safari e Firefox non verificati.</li></ul></li></ul><h3 id="§2-9-conflitti" tabindex="-1">§2.9 Conflitti <a class="header-anchor" href="#§2-9-conflitti" aria-label="Permalink to &quot;§2.9 Conflitti&quot;">​</a></h3><ul><li><strong>«Nessuna perdita silenziosa»</strong> [nuovo]: prima che un merge sostituisca contenuto locale non ancora sul server, il client ne prende uno snapshot nella history locale (<code>pre-sync-overwrite</code>).</li></ul><h3 id="§3-1-convenzioni-generali" tabindex="-1">§3.1 Convenzioni generali <a class="header-anchor" href="#§3-1-convenzioni-generali" aria-label="Permalink to &quot;§3.1 Convenzioni generali&quot;">​</a></h3><ul><li><strong>Codici d&#39;errore</strong> (ADR-0009/0011/0021): aggiungere <code>NAME_IN_USE</code> (409) e <code>INVALID_STATE</code> (409).</li><li><strong>Limiti di richiesta</strong> [nuovo]: <ul><li>timeout di 60 s solo per le operazioni JSON; nessun timeout per SSE, tus, blob ed export;</li><li>corpo JSON al massimo 8 MiB (oltre: <code>413 FILE_TOO_LARGE</code>);</li><li>limite di richieste per IP calcolato sull&#39;IP del client, dietro i proxy di <code>TRUSTED_PROXIES</code>; i probe di salute sono esenti.</li></ul></li><li><strong>Contratto:</strong> tus e <code>GET /events</code> sono fuori da OpenAPI (handler dedicati, ADR-0009).</li></ul><h3 id="§3-2-2-schema-del-database" tabindex="-1">§3.2.2 Schema del database <a class="header-anchor" href="#§3-2-2-schema-del-database" aria-label="Permalink to &quot;§3.2.2 Schema del database&quot;">​</a></h3><ul><li><strong>Aggiunte</strong> (ADR-0009/0012/0021): <ul><li><code>file_revisions.op_id</code> con <code>UNIQUE (vault_id, op_id)</code>;</li><li>tabelle <code>vault_blobs</code>, <code>uploads</code>, <code>config_profile_versions</code>, <code>storage_snapshots</code>;</li><li>indici su <code>audit_log(actor_id, at)</code> e <code>(action, at)</code>;</li><li><code>users.deleted_at</code>, <code>users.purged_at</code> (migrazione 0006).</li></ul></li><li><strong>Modifica:</strong> <code>vaults</code> ha un indice univoco parziale sul nome, solo per i vault attivi (<code>deleted_at IS NULL</code>).</li><li><strong>Chiavi di <code>settings</code>:</strong> <code>privacy.account_purge_days</code> e la revisione della configurazione.</li></ul><h3 id="§3-3-autorizzazione" tabindex="-1">§3.3 Autorizzazione <a class="header-anchor" href="#§3-3-autorizzazione" aria-label="Permalink to &quot;§3.3 Autorizzazione&quot;">​</a></h3><ul><li><strong>§3.3.2</strong> (ADR-0011): <code>404</code> per uno share inesistente, revocato, scaduto o estraneo; <code>403 FORBIDDEN</code> per un livello insufficiente su una risorsa visibile.</li></ul><h3 id="§3-4-sincronizzazione" tabindex="-1">§3.4 Sincronizzazione <a class="header-anchor" href="#§3-4-sincronizzazione" aria-label="Permalink to &quot;§3.4 Sincronizzazione&quot;">​</a></h3><ul><li><strong>§3.4.2 Esclusi dal sync</strong> (ADR-0022): aggiungere <code>.memobrain-tmp-*</code> (file temporanei di scrittura atomica, rimossi dopo più di 1 minuto).</li><li><strong>§3.4.2 Dimensione massima</strong> [nuovo]: il client controlla il limite (<code>sync.max_file_size_bytes</code>, default 100 MB) prima di leggere e cifrare. Vedi la decisione 8 del §1 sull&#39;allineamento con <code>files.max_size_bytes</code>.</li><li><strong>§3.4.3 <code>sync.db</code></strong> (ADR-0009): un <code>sync.db</code> per vault, quindi senza <code>vault_id</code>; <code>base_rev</code>, distinta da <code>server_rev</code>, come antenato del merge a tre vie; <code>outbox</code> per path; <code>conflicts</code> con <code>copy_path</code>, <code>strategy</code>, <code>detail</code>.</li><li><strong>§3.4.4</strong>: <ul><li><strong>B</strong> (ADR-0022): <code>410 CURSOR_EXPIRED</code> anche con un cursore oltre <code>last_seq</code> (dopo un PITR); nel bootstrap i file persi dal server vanno nel <code>.trash/</code> locale.</li><li><strong>C.3</strong> (ADR-0009): l&#39;esito resta per operazione; l&#39;implementazione usa una transazione per batch, con fallback a una per operazione.</li></ul></li><li><strong>§3.4.6 Impostazioni sincronizzate</strong> (ADR-0015/0016/0018/0024): aggiungere <code>bookmarks.json</code>, <code>daily.json</code>, <code>history.json</code>, <code>drawing.json</code>. Per <code>graph.json</code> serve una decisione: ADR-0013 non la prende.</li><li><strong>§3.4.7 Scope</strong> (ADR-0011): <ul><li><code>scope=share:{id}</code> vale per <code>tree</code>, <code>commit</code>, <code>blobs:check</code>, blob, tus e revisioni;</li><li>un&#39;operazione fuori dallo share risponde <code>NOT_FOUND</code>;</li><li>uno share di documento ammette solo <code>modify</code> e <code>delete</code>.</li></ul></li></ul><h3 id="§3-5-api-rest" tabindex="-1">§3.5 API REST <a class="header-anchor" href="#§3-5-api-rest" aria-label="Permalink to &quot;§3.5 API REST&quot;">​</a></h3><ul><li><strong>§3.5.1</strong>: <ul><li><code>GET /client-config</code> + <code>web_client_id</code> (ADR-0011);</li><li><code>GET /me/export</code>, <code>DELETE /me</code> con <code>{confirm, acknowledge_data_loss?}</code> (ADR-0021).</li></ul></li><li><strong>§3.5.2 Export</strong> (ADR-0012): <ul><li><code>GET /exports/{id}</code> diventa <code>GET /vaults/{vid}/exports/{eid}</code>, più <code>GET /vaults/{vid}/exports/{eid}/download</code>;</li><li>streaming oltre 512 MB → <code>409 INVALID_STATE</code>;</li><li><code>download_url</code> presigned solo con <code>S3_PUBLIC_ENDPOINT</code>.</li></ul></li><li><strong>§3.5.3</strong> (ADR-0009): <code>path_key</code> (<code>hmac1:</code>) in <code>CommitOp</code> per i vault privati; <code>GET /events?known=&lt;vault:seq,...&gt;</code> con eventi raggruppati per vault.</li><li><strong>§3.5.5 Admin</strong> (ADR-0012/0021): <ul><li>nuove rotte: <code>/admin/users/{id}/devices</code>, <code>/admin/users/{id}/sessions</code>, <code>/admin/storage/bulk-quota</code> (max 500), <code>/admin/config-profiles/{id}/versions</code>, <code>…/versions/{v}:restore</code>, <code>/admin/audit-log.csv</code> (≤ 50.000 righe);</li><li><code>409 INVALID_STATE</code> per auto-sospensione e per l&#39;ultimo admin attivo;</li><li><code>quota_bytes</code> assente o <code>null</code> vale il default.</li></ul></li></ul><h3 id="§3-6-grpc" tabindex="-1">§3.6 gRPC <a class="header-anchor" href="#§3-6-grpc" aria-label="Permalink to &quot;§3.6 gRPC&quot;">​</a></h3><ul><li><strong><code>AccountChanged</code></strong> (ADR-0012): <code>kind</code> può valere <code>suspended</code>, <code>activated</code> o <code>quota_changed</code>.</li><li><strong>Canali NOTIFY:</strong> <code>share_changed</code>, <code>config_changed</code>, <code>account_changed</code>.</li></ul><h3 id="§3-7-sicurezza" tabindex="-1">§3.7 Sicurezza <a class="header-anchor" href="#§3-7-sicurezza" aria-label="Permalink to &quot;§3.7 Sicurezza&quot;">​</a></h3><ul><li><strong>CSP Web UI</strong> (ADR-0012/0029): <ul><li><code>&#39;wasm-unsafe-eval&#39;</code> per Argon2id e per il core; <code>unsafe-inline</code> e <code>unsafe-eval</code> restano vietati;</li><li>CSP dedicata al workbench (<code>blob:</code>, worker).</li></ul></li><li><strong>Supply chain</strong> (ADR-0021): <ul><li>workflow <code>security.yml</code>: govulncheck bloccante, <code>yarn npm audit</code> bloccante sulle severità alte, SBOM syft, gitleaks (da rendere bloccante), CSP/SRI, test vector;</li><li>esecuzione su PR, su <code>main</code> e ogni lunedì.</li></ul></li></ul><h3 id="§3-8-e2ee" tabindex="-1">§3.8 E2EE <a class="header-anchor" href="#§3-8-e2ee" aria-label="Permalink to &quot;§3.8 E2EE&quot;">​</a></h3><ul><li><strong>§3.8.2, riga «Envelope»</strong> (ADR-0034): <code>0x02 ‖ nonce ‖ AES-256-GCM(KEK, VMK; AAD = &quot;memobrain/v2/envelope&quot; ‖ vault_id ‖ kind) ‖ tag</code>; il v1 (60 byte, senza AAD) resta accettato in lettura; pinning per vault dopo il primo v2.</li><li><strong>§3.8.2, riga «Cache locale»</strong> [nuovo]: <ul><li>timeout di blocco per inattività da impostazione per dispositivo e da Config Profile (<code>security.vault_lock_minutes</code>, 0–1440, default 0 = mai);</li><li>precedenza: chiave bloccata dall&#39;admin &gt; scelta dell&#39;utente &gt; default dell&#39;admin;</li><li>«inattività» = nessun uso della chiave, sync compresa.</li></ul></li><li><strong>§3.8.7</strong> (ADR-0034): nuovi vettori positivi e negativi per l&#39;envelope v2.</li></ul><h3 id="§4-struttura-del-progetto" tabindex="-1">§4 Struttura del progetto <a class="header-anchor" href="#§4-struttura-del-progetto" aria-label="Permalink to &quot;§4 Struttura del progetto&quot;">​</a></h3><ul><li><strong>§4.1</strong> (ADR-0032): <code>Makefile</code> diventa <code>Taskfile.yml</code> (Task v3, pinnato in <code>tools/go.mod</code>), e <code>make &lt;target&gt;</code> diventa <code>task &lt;target&gt;</code>.</li><li><strong>§4.2</strong> (ADR-0025/0026/0029/0035): <ul><li><code>vite.config.ts</code> diventa <code>scripts/esbuild.mjs</code> + <code>vitest.config.ts</code>;</li><li>il frontend vive in <code>packages/workbench</code> (condiviso con il web);</li><li><code>sidebar/</code> contiene a sinistra File e Struttura; a destra Proprietà, Tag, Link, ShowSlide e Statistiche;</li><li>nuova cartella <code>src/shell/</code>, con <code>statusbar</code> se si accetta ADR-0035.</li></ul></li><li><strong>§4.3</strong> (ADR-0033): <ul><li><code>db/queries/&lt;modulo&gt;.sql</code> genera <code>internal/&lt;modulo&gt;/&lt;modulo&gt;db</code>; wrapper in <code>internal/&lt;modulo&gt;/exported.go</code>;</li><li>nuovi moduli <code>settings</code> e <code>access</code>;</li><li>mappa di proprietà ed eccezioni in <code>internal/db/ownership_test.go</code>;</li><li><code>depguard</code> al posto di <code>go-arch-lint</code>.</li></ul></li><li><strong>§4.4</strong> (ADR-0025/0029): <code>web/scripts/esbuild.mjs</code> (SRI sha384); <code>src/workbench/</code> (bridge, worker, <code>opfs-fs.ts</code>).</li><li><strong>§4.5</strong> (ADR-0031/0032): <ul><li><code>task gen</code>;</li><li>CI: <code>ci.yml</code> senza build; build e pubblicazione solo dal tag (<code>release.yml</code>); e2e, integrazione e <code>test-wasm</code> lanciati a mano;</li><li><strong>Release:</strong> testo di ADR-0031 sui rilasci non firmati.</li></ul></li></ul><h3 id="appendice-a-—-requisiti-non-funzionali" tabindex="-1">Appendice A — Requisiti non funzionali <a class="header-anchor" href="#appendice-a-—-requisiti-non-funzionali" aria-label="Permalink to &quot;Appendice A — Requisiti non funzionali&quot;">​</a></h3><ul><li><strong>Prestazioni</strong> (ADR-0020): <ul><li>verifica con dataset deterministici, <code>task perf</code> e baseline in <code>docs/perf/</code>, eseguita a mano (il nightly è stato rimosso);</li><li>budget del bundle: console ≤ 700/1000 kB, workbench ≤ 2500/23000 kB, WASM gzip con core ≤ 8 MB e sqlite ≤ 1,5 MB.</li></ul></li><li><strong>Grafo</strong> (ADR-0013): «10.000 nodi a ≥ 30 fps» con Canvas 2D; WebGL come riserva.</li><li><strong>Disponibilità</strong> (ADR-0022): il chaos test verifica il 99,9 % solo nella finestra di prova; la prova di ripristino è <code>restore-drill.sh</code>. RTO reale non misurato.</li><li><strong>Piattaforme</strong> (ADR-0031): Windows amd64/arm64, Linux amd64/arm64, macOS universale.</li></ul><h3 id="appendice-b-—-roadmap" tabindex="-1">Appendice B — Roadmap <a class="header-anchor" href="#appendice-b-—-roadmap" aria-label="Permalink to &quot;Appendice B — Roadmap&quot;">​</a></h3><p>Da «Post-1.0» si tolgono Slides e Random note. Si aggiunge la riga M8–M10 (shell, workbench web, pipeline di rilascio).</p><hr><h2 id="_4-incoerenze-da-correggere-negli-adr-non-nello-spec" tabindex="-1">4. Incoerenze da correggere negli ADR (non nello spec) <a class="header-anchor" href="#_4-incoerenze-da-correggere-negli-adr-non-nello-spec" aria-label="Permalink to &quot;4. Incoerenze da correggere negli ADR (non nello spec)&quot;">​</a></h2><ul><li><strong>ADR-0010:</strong> la versione <code>@excalidraw/excalidraw@0.18.1</code> è superata da ADR-0028 (fork 0.18.145). Va aggiunto un rinvio.</li><li><strong>ADR-0024:</strong> la sezione «Conseguenze» cita il sotto-flag <code>drawing_scripts</code>, mentre il codice e lo schema usano <code>drawing_actions</code> (decisione 26).</li><li><strong>ADR-0026:</strong> chiama la stessa tab sia «Segnalibri» sia «Link»; nel codice è <em>Link</em>.</li><li><strong>ADR-0013:</strong> non dice se <code>.memobrain/graph.json</code> è sincronizzato (§3.4.6).</li></ul><h2 id="_5-limiti-da-dichiarare-nello-spec-sintesi" tabindex="-1">5. Limiti da dichiarare nello spec (sintesi) <a class="header-anchor" href="#_5-limiti-da-dichiarare-nello-spec-sintesi" aria-label="Permalink to &quot;5. Limiti da dichiarare nello spec (sintesi)&quot;">​</a></h2><p>Ogni ADR elenca i propri; nello spec vanno almeno questi.</p><ul><li><strong>Ricerca e indice:</strong><ul><li>regex su 50.000 note oltre i 200 ms;</li><li><code>index.db</code> ≈ 5,3 volte il testo.</li></ul></li><li><strong>Collegamenti e sync:</strong><ul><li>il rename non aggiorna i link dentro i canvas;</li><li>nessuna cessione di proprietà dei vault;</li><li>un file messo da parte per dimensione riprova solo quando cambia.</li></ul></li><li><strong>Cloud:</strong><ul><li>account Keycloak disabilitato, non eliminato, con la cancellazione GDPR;</li><li>nessuna retention automatica di <code>audit_log</code>;</li><li>outage del database come <code>500 INTERNAL</code> (manca <code>UNAVAILABLE</code>).</li></ul></li><li><strong>Workbench web:</strong><ul><li>Safari e Firefox non verificati;</li><li>nessuna PWA offline;</li><li>core WASM circa 4,5 volte più lento del nativo.</li></ul></li><li><strong>Editor e import:</strong><ul><li>footnote inline non rese in Live Preview;</li><li>Keep HTML senza data di creazione;</li><li>Apple Notes P2.</li></ul></li><li><strong>Rilascio:</strong> installer non firmati finché mancano i certificati.</li></ul><h2 id="_6-dopo-il-recepimento" tabindex="-1">6. Dopo il recepimento <a class="header-anchor" href="#_6-dopo-il-recepimento" aria-label="Permalink to &quot;6. Dopo il recepimento&quot;">​</a></h2><p>Gli ADR recepiti passano a <strong>accettata</strong> nell&#39;indice <code>docs/adr/README.md</code>: 0009–0024, 0026–0030 e 0032–0035, più la nota di 0031. La checklist di rilascio (<code>docs/release/v1.0.0-checklist.md</code> §1) segna come fatto «Recepire nello spec le deviazioni proposte negli ADR». Il <code>CLAUDE.md</code> rimanda alla v1.2.</p>',67)])])}const m=o(d,[["render",l]]);export{g as __pageData,m as default};
